#!/usr/bin/env bash
# 3版目の拡張：新しい敵（エイ・ウニ）、お店のヤドカリ、新しいカードの絵、お守り（レリック）の絵
cd ~/Projects/canopus-dive
P="16-bit retro pixel art game sprite, crisp hard-edged pixels, no anti-aliasing, limited palette, dark 1-pixel outline, cute chibi style, all-ages."
E="Exactly 4 frames of the SAME creature in one horizontal row, evenly spaced with wide gaps, same size and same design in every frame, facing left. Frame 1: idle. Frame 2: idle with a slight bob (animation frame). Frame 3: hurt, flashing, eyes as X. Frame 4: attacking. Plain flat pure green (#00FF00) background with nothing else, no text, no grid."
I="matching the style of the reference icons, each icon a simple bold symbol on its own, plain flat pure green (#00FF00) background, no text, no letters, no grid. Do not use pure green inside the icons."
gen(){ tools/gen_image.sh "$@" & }
gen art/raw/px_ei.png "$P $E Creature: a wide dark-blue manta ray with a pale belly, small sleepy eyes and a long thin tail, gliding. Frame 4: swooping forward with wings raised."
gen art/raw/px_uni.png "$P $E Creature: a round purple-black sea urchin covered in long sharp spines, two tiny grumpy eyes peeking between the spines. Frame 4: spines bristling outward, bigger and pointier."
gen art/raw/px_yadokari.png "$P Exactly 4 frames of the SAME character in one horizontal row, evenly spaced with wide gaps, same size and same design in every frame, facing right. Plain flat pure green (#00FF00) background with nothing else, no text, no grid. Character: a friendly hermit crab shopkeeper living in a big spiral seashell decorated with tiny lanterns and price tags, wearing small round glasses and a merchant's apron, orange-red claws. Frame 1: idle, smiling. Frame 2: happy, waving a claw. Frame 3: surprised, sweat drop. Frame 4: proudly presenting a shiny gold coin with a claw."
wait
gen art/raw/icons3.png "$P A sprite sheet of 8 separate square game card icons for an underwater adventure, in 2 rows of 4 with wide gaps, $I Row 1: 1 an orca's open jaws biting with sharp white teeth (a strong bite), 2 a fast blue water current arrow sweeping in a straight line with streaks, 3 a long sharp white narwhal-like horn piercing through bubbles, 4 a swirling water hook pulling a small fish backward (undertow). Row 2: 5 a curtain of shimmering pink and white bubbles (a hiding curtain), 6 a small blue axolotl dragon with pink wings cheering with tiny pom-poms and sparkles, 7 an old rolled treasure map with a red X and gold coins, 8 a messy black ink blot splat with sad bubbles (a useless junk card)." assets/images/ui/icons.png
gen art/raw/relics.png "$P A sprite sheet of 12 separate square treasure item icons (magic charms) for an underwater adventure, in 3 rows of 4 with wide gaps, $I Row 1: 1 a big white orca fang on a string, 2 an orange inflatable swim float ring, 3 a pink coral branch charm with a ribbon, 4 a shiny golden fish scale. Row 2: 5 a scallop seashell shaped like a small shield, 6 a tiny surfboard painted blue and yellow, 7 a glowing anglerfish-style lantern, 8 a brown leather satchel bag. Row 3: 9 a pink ribbon bow with small bat wings, 10 a spiral cone seashell, 11 a blue gill fan with bubbles, 12 an old golden key with a star-shaped handle." assets/images/ui/icons.png
wait
